// Calculate servo angles from coordinates
void moveToTarget(float x, float y, float z) {
  float baseAngle = atan2(y, x) * 180.0 / PI;
  pwm.setPWM(BASE_SERVO, 0, mapAngleToPulse(baseAngle));
  // Forward kinematics & shoulder trajectory
  delay(150);
}

// Read RPLiDAR scan packet
void processLiDARData() {
  if (lidar.isOpen()) {
    rplidar_response_measurement_node_hq_t nodes[8192];
    size_t count = sizeof(nodes)/sizeof(nodes[0]);
    lidar.getScanData(nodes, count);
    filterObstacles(nodes, count);
  }
}

// Soil moisture trigger logic
int rawSoil = analogRead(SOIL_PIN);
float moisturePct = map(rawSoil, AIR_VAL, WATER_VAL, 0, 100);
if (moisturePct < 35.0) {
  digitalWrite(RELAY_PUMP, HIGH); // Water the plant
  displayWaterAlert();
}

// Unity OpenXR interaction event
public void OnGearGrab(SelectEnterEventArgs args) {
  HapticFeedback.SendImpulse(args.interactorObject, 0.4f, 0.1f);
  CalculateTorqueTransfer();
}

// Map glove sensor voltage to servo angles
for(int i = 0; i < 5; i++) {
  int raw = analogRead(flexPins[i]);
  int angle = map(raw, flatResistance[i], bentResistance[i], 0, 180);
  angle = constrain(angle, 0, 180);
  servos[i].write(angle);
}
